solution.code:
Optional<String> present = Optional.of("Java");
Optional<String> empty = Optional.empty();

System.out.println(present.isPresent()); // true
System.out.println(empty.isPresent());   // false
System.out.println(present.isEmpty());   // false (Java 11+)
System.out.println(empty.isEmpty());     // true  (Java 11+)

System.out.println(present.get()); // Java
try {
    empty.get(); // throws!
} catch (java.util.NoSuchElementException e) {
    System.out.println("get() on empty throws: " + e.getClass().getSimpleName());
}

starterCode:
Optional<String> present = Optional.of("Found!");
Optional<String> empty = Optional.empty();
// Use orElse with a default string
// Use orElseGet with a Supplier
// Use orElseThrow with a custom exception

solution.code:
// orElse — always evaluates the default expression
String v1 = empty.orElse("default");
String v2 = present.orElse("default"); // still returns "Found!"
System.out.println(v1); // default
System.out.println(v2); // Found!

// orElseGet — Supplier only invoked if empty (lazy)
String v3 = empty.orElseGet(() -> "computed-" + System.currentTimeMillis());
System.out.println(v3);

// orElseThrow — throw custom exception if empty
try {
    empty.orElseThrow(() -> new IllegalStateException("Value required!"));
} catch (IllegalStateException e) {
    System.out.println("Caught: " + e.getMessage());
}
String v4 = present.orElseThrow(() -> new IllegalStateException("unreachable"));
System.out.println(v4); // Found!

