// Anti-pattern 1: Optional as parameter
void greet(Optional<String> name) {
    if (name.isPresent()) System.out.println("Hello " + name.get());
    else System.out.println("Hello stranger");
}

// Anti-pattern 2: get() without guard
Optional<String> opt = Optional.ofNullable(System.getenv("MY_VAR"));
String value = opt.get(); // may throw!

// Anti-pattern 3: of() on nullable
String s = null;
Optional<String> bad = Optional.of(s); // NPE!

solution.code:
// Fix 1: Use overloading, not Optional param
void greet(String name) { System.out.println("Hello " + name); }
void greet() { System.out.println("Hello stranger"); }
// Or: accept String directly, handle null inside
void greetFixed(String name) {
    System.out.println("Hello " + Optional.ofNullable(name).orElse("stranger"));
}

// Fix 2: Use orElse instead of get()
String value = Optional.ofNullable(System.getenv("MY_VAR"))
    .orElse("default-value");
System.out.println(value);

// Fix 3: Use ofNullable
String s = null;
Optional<String> safe = Optional.ofNullable(s); // OK, returns empty
System.out.println(safe); // Optional.empty

starterCode:
Map<String, String> config = Map.of("timeout", "30", "retries", "abc", "port", "-1");
// Get 'timeout' as positive integer or throw
// Get 'retries' as positive integer or throw
// Get 'missing' as positive integer or throw

solution.code:
java.util.function.Function<String, Optional<Integer>> parsePositiveInt = s -> {
    try {
        return Optional.of(Integer.parseInt(s)).filter(n -> n > 0);
    } catch (NumberFormatException e) {
        return Optional.empty();
    }
};

java.util.function.Function<String, Integer> getPositiveConfig = key ->
    Optional.ofNullable(config.get(key))
        .flatMap(parsePositiveInt)
        .orElseThrow(() -> new IllegalArgumentException(
            "Config '" + key + "' must be a positive integer"));

System.out.println(getPositiveConfig.apply("timeout")); // 30
try { getPositiveConfig.apply("retries"); } // abc not parseable
catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
try { getPositiveConfig.apply("port"); }   // -1 not positive
catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
try { getPositiveConfig.apply("missing"); } // not in map
catch (IllegalArgumentException e) { System.out.println(e.getMessage()); }
